use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        // (1) length is the sum of lengths
        res@.len() == a@.len() + b@.len(),

        // (2) prefix equals `a`
        forall|i: int|
            0 <= i && i < a@.len()
            ==> res@[i] == a@[i],

        // (3) suffix equals `b`
        forall|j: int|
            0 <= j && j < b@.len()
            ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            res@.len() == i as int,
            forall|k: int| 0 <= k && k < i as int ==> res@[k] == a@[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }

    let a_len = a.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j <= b.len(),
            res@.len() == a_len as int + j as int,
            forall|k: int| 0 <= k && k < a_len as int ==> res@[k] == a@[k],
            forall|k: int| 0 <= k && k < j as int ==> res@[a_len as int + k] == b@[k],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!

